import{_ as i,a0 as l,w as o,s as r,I as n,x as a,a1 as e,A as p,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const q=JSON.parse('{"title":"用 Bash 腳本發送新用户帳户創建的郵件 | LCTT x X-CMD","titleTemplate":false,"description":"用 Bash 腳本發送新用户帳户創建的郵件 | LCTT (201909) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 Bash 腳本發送新用户帳户創建的郵件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 Bash 腳本發送新用户帳户創建的郵件 | LCTT (201909) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201909/20190912 Bash Script to Send a Mail About New User Account Creation","title":"用 Bash 腳本發送新用户帳户創建的郵件","tag":"201909","desc":""},"relativePath":"201909/20190912 Bash Script to Send a Mail About New User Account Creation.md","filePath":"[post].md"}'),u={name:"201909/20190912 Bash Script to Send a Mail About New User Account Creation.md"};function g(h,s,c,m,b,k){const t=l("Link");return o(),r("div",null,[s[17]||(s[17]=n("h1",{id:"用-bash-腳本發送新用户帳户創建的郵件",tabindex:"-1"},[a("用 Bash 腳本發送新用户帳户創建的郵件 "),n("a",{class:"header-anchor",href:"#用-bash-腳本發送新用户帳户創建的郵件","aria-label":"Permalink to “用 Bash 腳本發送新用户帳户創建的郵件”"},"​")],-1)),s[18]||(s[18]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/201909/20/093308a615tcuiopctvp5t.jpg",alt:""})],-1)),s[19]||(s[19]=n("p",null,"出於某些原因，你可能需要跟蹤 Linux 上的新用户創建信息。同時，你可能需要通過郵件發送詳細信息。這或許是審計目標的一部分，或者安全團隊出於跟蹤目的可能希望對此進行監控。",-1)),s[20]||(s[20]=n("p",null,"我們可以通過其他方式進行此操作，正如我們在上一篇文章中已經描述的那樣。",-1)),n("ul",null,[n("li",null,[e(t,{href:"https://www.2daygeek.com/linux-bash-script-to-monitor-user-creation-send-email/"},{default:p(()=>[...s[0]||(s[0]=[a("在系統中創建新用户帳户時發送郵件的 Bash 腳本",-1)])]),_:1})])]),s[21]||(s[21]=n("p",null,"Linux 有許多開源監控工具可以使用。但我不認為他們有辦法跟蹤新用户創建過程，並在發生時提醒管理員。",-1)),s[22]||(s[22]=n("p",null,"那麼我們怎樣才能做到這一點？",-1)),s[23]||(s[23]=n("p",null,"我們可以編寫自己的 Bash 腳本來實現這一目標。我們過去寫過許多有用的 shell 腳本。如果你想了解，請進入下面的鏈接。",-1)),n("ul",null,[n("li",null,[e(t,{href:"https://www.2daygeek.com/category/shell-script/"},{default:p(()=>[...s[1]||(s[1]=[a("如何使用 shell 腳本自動化日常活動？",-1)])]),_:1})])]),s[24]||(s[24]=d(`<h3 id="這個腳本做了什麼" tabindex="-1">這個腳本做了什麼？ <a class="header-anchor" href="#這個腳本做了什麼" aria-label="Permalink to “這個腳本做了什麼？”">​</a></h3><p>這將每天兩次（一天的開始和結束）備份 <code>/etc/passwd</code> 文件，這將使你能夠獲取指定日期的新用户創建詳細信息。</p><p>我們需要添加以下兩個 cron 任務來複制 <code>/etc/passwd</code> 文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># crontab -e</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1 0 * * * cp /etc/passwd /opt/scripts/passwd-start-$(date +&quot;%Y-%m-%d&quot;)</span></span>
<span class="line"><span>59 23 * * * cp /etc/passwd /opt/scripts/passwd-end-$(date +&quot;%Y-%m-%d&quot;)</span></span></code></pre></div><p>它使用 <code>diff</code> 命令來檢測文件之間的差異，如果發現與昨日有任何差異，腳本將向指定 email 發送新用户詳細信息。</p><p>我們不用經常運行此腳本，因為用户創建不經常發生。但是，我們計劃每天運行一次此腳本。</p><p>這樣，你可以獲得有關新用户創建的綜合報告。</p><p><strong>注意：</strong>我們在腳本中使用了我們的電子郵件地址進行演示。因此，我們要求你用自己的電子郵件地址。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /opt/scripts/new-user-detail.sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>mv /opt/scripts/passwd-start-$(date --date=&#39;yesterday&#39; &#39;+%Y-%m-%d&#39;) /opt/scripts/passwd-start</span></span>
<span class="line"><span>mv /opt/scripts/passwd-end-$(date --date=&#39;yesterday&#39; &#39;+%Y-%m-%d&#39;) /opt/scripts/passwd-end</span></span>
<span class="line"><span>ucount=$(diff /opt/scripts/passwd-start /opt/scripts/passwd-end | grep &quot;&gt;&quot; | cut -d&quot;:&quot; -f6 | cut -d&quot;/&quot; -f3 | wc -l)</span></span>
<span class="line"><span>if [ $ucount -gt 0 ]</span></span>
<span class="line"><span>then</span></span>
<span class="line"><span>  SUBJECT=&quot;ATTENTION: New User Account is created on server : \`date --date=&#39;yesterday&#39; &#39;+%b %e&#39;\`&quot;</span></span>
<span class="line"><span>  MESSAGE=&quot;/tmp/new-user-logs.txt&quot;</span></span>
<span class="line"><span>  TO=&quot;2daygeek@gmail.com&quot;</span></span>
<span class="line"><span>  echo  &quot;Hostname: \`hostname\`&quot; &gt;&gt; $MESSAGE</span></span>
<span class="line"><span>  echo -e &quot;\\n&quot; &gt;&gt; $MESSAGE</span></span>
<span class="line"><span>  echo &quot;The New User Details are below.&quot; &gt;&gt; $MESSAGE</span></span>
<span class="line"><span>  echo &quot;+------------------------------+&quot; &gt;&gt; $MESSAGE</span></span>
<span class="line"><span>  diff /opt/scripts/passwd-start /opt/scripts/passwd-end | grep &quot;&gt;&quot; | cut -d&quot;:&quot; -f6 | cut -d&quot;/&quot; -f3 &gt;&gt;  $MESSAGE</span></span>
<span class="line"><span>  echo &quot;+------------------------------+&quot; &gt;&gt; $MESSAGE</span></span>
<span class="line"><span>  mail -s &quot;$SUBJECT&quot; &quot;$TO&quot; &lt; $MESSAGE</span></span>
<span class="line"><span>  rm $MESSAGE</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p>給 <code>new-user-detail.sh</code> 文件添加可執行權限。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod +x /opt/scripts/new-user-detail.sh</span></span></code></pre></div><p>最後添加一個 cron 任務來自動執行此操作。它在每天早上 7 點運行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># crontab -e</span></span>
<span class="line"><span></span></span>
<span class="line"><span>0 7 * * * /bin/bash /opt/scripts/new-user.sh</span></span></code></pre></div><p><strong>注意：</strong>你會在每天早上 7 點都會收到一封關於昨日詳情的郵件提醒。</p><p><strong>輸出：</strong>輸出與下面的輸出相同。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># cat /tmp/new-user-logs.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Hostname: CentOS.2daygeek.com</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The New User Details are below.</span></span>
<span class="line"><span>+------------------------------+</span></span>
<span class="line"><span>tuser3</span></span>
<span class="line"><span>+------------------------------+</span></span></code></pre></div><hr>`,17)),n("p",null,[s[3]||(s[3]=a("via: ",-1)),e(t,{href:"https://www.2daygeek.com/linux-shell-script-to-monitor-user-creation-send-email/"},{default:p(()=>[...s[2]||(s[2]=[a("https://www.2daygeek.com/linux-shell-script-to-monitor-user-creation-send-email/",-1)])]),_:1})]),n("p",null,[s[8]||(s[8]=a("作者：",-1)),e(t,{href:"https://www.2daygeek.com/author/magesh/"},{default:p(()=>[...s[4]||(s[4]=[a("Magesh Maruthamuthu",-1)])]),_:1}),s[9]||(s[9]=a(" 選題：",-1)),e(t,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[5]||(s[5]=[a("lujun9972",-1)])]),_:1}),s[10]||(s[10]=a(" 譯者：",-1)),e(t,{href:"https://github.com/geekpi"},{default:p(()=>[...s[6]||(s[6]=[a("geekpi",-1)])]),_:1}),s[11]||(s[11]=a(" 校對：",-1)),e(t,{href:"https://github.com/wxy"},{default:p(()=>[...s[7]||(s[7]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[14]||(s[14]=a("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[12]||(s[12]=[a("LCTT",-1)])]),_:1}),s[15]||(s[15]=a(" 原創編譯，",-1)),e(t,{href:"https://linux.cn/"},{default:p(()=>[...s[13]||(s[13]=[a("Linux中國",-1)])]),_:1}),s[16]||(s[16]=a(" 榮譽推出",-1))])])}const S=i(u,[["render",g]]);export{q as __pageData,S as default};
